"use strict";exports.id=8106,exports.ids=[8106],exports.modules={8106:(a,b,c)=>{c.d(b,{DW:()=>z,Ij:()=>D,LZ:()=>k,S1:()=>C,SC:()=>o,UL:()=>l,ZR:()=>r,bb:()=>f,bw:()=>t,c3:()=>p,dv:()=>m,f8:()=>n,f9:()=>j,fN:()=>q,gA:()=>h,gD:()=>w,iW:()=>y,iv:()=>i,oS:()=>A,qI:()=>x,tF:()=>s,uj:()=>g,um:()=>u,yb:()=>v});var d=c(98244);let e=(0,d.wP)("makkah-to-jeddah-airport"),f=(0,d.wP)("jeddah-airport-to-makkah"),g=(0,d.wP)("makkah-to-jeddah"),h=(0,d.wP)("makkah-to-madinah"),i=(0,d.wP)("makkah-to-taif"),j=(0,d.wP)("makkah-to-riyadh");(0,d.wP)("makkah-to-madinah-airport");let k="15–30 minutes",l=[{label:"Makkah → JED Airport",value:`${e.km} km \xb7 ${e.time}`},{label:"Makkah → Madinah",value:`${h.km} km \xb7 ${h.time}`},{label:"Makkah → Taif",value:`${i.km} km \xb7 ${i.time}`},{label:"Flights",value:"We track your flight"},{label:"Drivers",value:"English- & Arabic-speaking"},{label:"Cancellation",value:"Free up to 24 hours before"},{label:"Payment",value:"Cash to the driver or bank transfer"},{label:"Companies",value:"Invoicing via our sister company"}],m=[{id:"airport",icon:"plane",label:"Jeddah Airport ↔ Makkah",short:`${f.km} km from JED`,answer:`A private car from King Abdulaziz International Airport (JED) to your Makkah hotel is about ${f.km} km (${f.time}). We track your flight, the driver meets you after baggage claim, and the fare is agreed before you travel. The return leg is booked the same way — pickup is worked back from your flight time.`,send:["Flight number and terminal","Makkah hotel name","Passengers and large bags","Return flight, if booking both ways"],href:"/routes/jeddah-airport-to-makkah",linkLabel:"Jeddah Airport to Makkah transfer",waPrefill:"Salam! Jeddah Airport ↔ Makkah transfer.\n• From: \n• To: \n• Date & time: \n• Flight number: \n• Passengers & luggage: \n• Vehicle (Sedan / SUV / Van): "},{id:"madinah",icon:"route",label:"Makkah ↔ Madinah",short:`${h.km} km, hotel to hotel`,answer:`Makkah to Madinah is about ${h.km} km — roughly ${h.time} of driving, plus the prayer and rest stops you ask for. A private car goes hotel to hotel with all your luggage in one vehicle, and the same route is available in reverse.`,send:["Makkah pickup address or hotel","Madinah hotel","Date and time","Passengers and large bags"],href:"/routes/makkah-to-madinah",linkLabel:"Makkah to Madinah private transfer",waPrefill:"Salam! Makkah ↔ Madinah transfer.\n• From: \n• To: \n• Date & time: \n• Passengers & luggage: \n• Vehicle (Sedan / SUV / Van): "},{id:"jeddah",icon:"route",label:"Makkah ↔ Jeddah",short:`${g.km} km to the city`,answer:`Makkah to anywhere in Jeddah is about ${g.km} km (${g.time}) — hotels, the Corniche, Al-Balad or a business meeting. For flights, book the Jeddah Airport leg instead, which is about ${e.km} km.`,send:["Makkah pickup","Jeddah address","Date and time","Passengers and bags"],href:"/routes/makkah-to-jeddah",linkLabel:"Makkah to Jeddah private car",waPrefill:"Salam! Makkah ↔ Jeddah transfer.\n• From: \n• To: \n• Date & time: \n• Passengers & luggage: \n• Vehicle (Sedan / SUV / Van): "},{id:"ziyarat",icon:"landmark",label:"Ziyarat by car",short:"Half-day, flexible waiting",answer:"A private car takes you between the Makkah sites you choose — for example Jabal al-Nour, Jabal Thawr, Mina, Muzdalifah, Arafat and Jannat al-Mu'alla — and waits at each stop. We provide the transport; we do not give religious guidance.",send:["Date and start time","Sites you want to visit","Passengers (elders or children?)","Pickup hotel"],href:"/services/makkah-ziyarat",linkLabel:"Makkah Ziyarat transportation",waPrefill:"Salam! Makkah Ziyarat by private car.\n• Date & start time: \n• Sites to visit: \n• Pickup hotel: \n• Passengers: \n• Vehicle (Sedan / SUV / Van): "},{id:"private-driver",icon:"clock",label:"Private driver by the hour",short:"Half-day or full day",answer:"One car and driver for a block of hours — the car waits outside each stop. Useful for a day of meetings, shopping and family errands across Makkah, or a flexible schedule around prayer times.",send:["Date and start time","Hours needed","Rough list of stops","Passengers"],href:"/locations/makkah/private-driver",linkLabel:"Private driver in Makkah",waPrefill:"Salam! Private driver in Makkah (hourly / full day).\n• Date & start time: \n• Hours needed: \n• Stops planned: \n• Passengers: \n• Vehicle (Sedan / SUV / Van): "},{id:"hotel",icon:"hotel",label:"Hotel pickup & drop-off",short:"Haram-area & Aziziyah hotels",answer:"Give us the hotel name and the leg you need — airport, station, another hotel or a city. Near Masjid al-Haram some roads close at prayer times, so the driver uses the nearest permitted drop-off point and tells you where to meet.",send:["Hotel name","Where you are going","Date and time","Passengers and bags"],href:"#hotels",linkLabel:"Makkah hotel transfers",waPrefill:"Salam! Makkah hotel transfer.\n• Hotel (pickup): \n• To (airport / station / hotel / city): \n• Date & time: \n• Passengers & luggage: "},{id:"intercity",icon:"route",label:"Taif, Riyadh & beyond",short:"One fare for the whole car",answer:`Beyond Madinah and Jeddah, the regular Makkah corridors are Taif up the escarpment (about ${i.km} km) and the long drive to Riyadh (about ${j.km} km). A private car runs door to door with rest and prayer stops on request.`,send:["Pickup address","Destination city","Date and time","Passengers and bags"],href:"#destinations",linkLabel:"Every route from Makkah",waPrefill:"Salam! Intercity trip from Makkah.\n• To (Taif / Riyadh / other): \n• Date & time: \n• Passengers & luggage: \n• Vehicle (Sedan / SUV / Van): "},{id:"corporate",icon:"briefcase",label:"Corporate & groups",short:"Delegations, teams, Umrah groups",answer:`Companies, Umrah group organisers and delegations get one point of contact and a written quote by email, with vehicles from executive sedans to coasters through our partner network. Larger coaches are arranged on request. ${d.D2}`,send:["Company or group name","Dates and trip list","Passengers per trip","Whether you need an invoice"],href:"/services/group-transport",linkLabel:"Group and corporate transportation",waPrefill:"Salam! Corporate / group transport in Makkah.\n• Company / group: \n• Dates & trips: \n• Passengers per trip: \n• Vehicle (Sedan / SUV / Van / Coaster): \n• Invoice needed?: "}],n=[{id:"jed",label:"Jeddah Airport",labelAr:"مطار جدة",x:130,y:120,slug:"makkah-to-jeddah-airport",reverseSlug:"jeddah-airport-to-makkah"},{id:"jeddah",label:"Jeddah",labelAr:"جدة",x:90,y:215,slug:"makkah-to-jeddah",reverseSlug:"jeddah-to-makkah"},{id:"madinah",label:"Madinah",labelAr:"المدينة المنورة",x:410,y:60,slug:"makkah-to-madinah",reverseSlug:"madinah-to-makkah"},{id:"taif",label:"Taif",labelAr:"الطائف",x:490,y:300,slug:"makkah-to-taif"},{id:"riyadh",label:"Riyadh",labelAr:"الرياض",x:560,y:175,slug:"makkah-to-riyadh",reverseSlug:"riyadh-to-makkah"}],o=[{slug:"jeddah-airport-to-makkah",label:"Jeddah Airport → Makkah",note:"The most-booked arrival. From the terminal straight to your Makkah hotel."},{slug:"makkah-to-jeddah-airport",label:"Makkah → Jeddah Airport",note:"Departure leg, with pickup worked back from your flight time."},{slug:"makkah-to-madinah",label:"Makkah → Madinah",note:"Hotel to hotel with prayer and rest stops on request."},{slug:"madinah-to-makkah",label:"Madinah → Makkah",note:"The return leg, or the start of an Umrah trip from Madinah."},{slug:"jeddah-to-makkah",label:"Jeddah city → Makkah",note:"From any Jeddah hotel or home, at any hour."},{slug:"makkah-to-jeddah",label:"Makkah → Jeddah city",note:"Back to a Jeddah hotel, the Corniche or Al-Balad."},{slug:"makkah-to-taif",label:"Makkah → Taif",note:"Up the Al Hada escarpment to the mountain city."},{slug:"makkah-to-riyadh",label:"Makkah → Riyadh",note:"The long cross-Kingdom drive, with stops planned in advance."}],p=[{slug:"jeddah-airport-to-swissotel-makkah",hotel:"Swissotel Al Maqam Makkah"},{slug:"jeddah-airport-to-fairmont-makkah",hotel:"Fairmont Makkah Clock Royal Tower"},{slug:"jeddah-airport-to-pullman-zamzam-makkah",hotel:"Pullman Zamzam Makkah"},{slug:"jeddah-airport-to-hilton-suites-makkah",hotel:"Hilton Suites Makkah"},{slug:"jeddah-airport-to-conrad-makkah",hotel:"Conrad Makkah"},{slug:"jeddah-airport-to-movenpick-makkah",hotel:"Movenpick Hajar Tower Makkah"},{slug:"jeddah-airport-to-makkah-clock-tower",hotel:"Makkah Clock Tower hotels"}],q=[{slug:"ajyad",name:"Ajyad",nameAr:"أجياد",what:"Beside Masjid al-Haram; Abraj Al Bait (Clock Tower) hotels"},{slug:"al-shubaikah",name:"Al Shubaikah",nameAr:"الشبيكة",what:"A short walk from the Haram on the Jeddah-road side"},{slug:"aziziyah",name:"Aziziyah",nameAr:"العزيزية",what:"Pilgrim hotels on the road towards Mina and Arafat"},{slug:"al-awali-makkah",name:"Al Awali",nameAr:"العوالي",what:"Southern Makkah, quick access to the expressway"},{slug:"al-mansour",name:"Al Mansour",nameAr:"المنصور",what:"Residential district with a short drive to the Haram"},{slug:"mina",name:"Mina",nameAr:"منى",what:"East of Makkah; permitted transport in the Hajj season"}],r=[{name:"Jabal al-Nour",nameAr:"جبل النور",note:"The mountain above the Cave of Hira, on the north side of Makkah. The car waits at the base."},{name:"Jabal Thawr",nameAr:"جبل ثور",note:"South of Makkah. The car waits at the base."},{name:"Mina",nameAr:"منى",note:"The tent valley east of Makkah, about 8 km from the Haram."},{name:"Muzdalifah",nameAr:"مزدلفة",note:"Between Mina and Arafat."},{name:"Arafat & Jabal al-Rahmah",nameAr:"عرفات وجبل الرحمة",note:"East of Makkah, on the plain of Arafat."},{name:"Jannat al-Mu'alla",nameAr:"جنة المعلاة",note:"The historic cemetery north of the Haram."}],s=[{id:"sedan",label:"Sedan",fleetSlug:"toyota-camry",forWho:"Individuals, couples and small groups with normal luggage",href:"/fleet/toyota-camry"},{id:"suv",label:"GMC / full-size SUV",fleetSlug:"gmc-yukon-xl",forWho:"Families and premium comfort with more luggage",href:"/fleet/gmc-yukon-xl"},{id:"staria",label:"Hyundai Staria",fleetSlug:"hyundai-staria",forWho:"Families and small groups travelling together",href:"/fleet/hyundai-staria"},{id:"hiace",label:"Toyota Hiace van",fleetSlug:"toyota-hiace",forWho:"Larger groups with a lot of luggage",href:"/fleet/toyota-hiace"},{id:"coaster",label:"Coaster / minibus",fleetSlug:"toyota-coaster",forWho:"Umrah groups, teams and delegations",href:"/fleet/toyota-coaster"}],t=[{title:"Prayer-time road closures",body:"Roads around Masjid al-Haram close or slow at prayer times. Your driver uses the nearest permitted drop-off point and tells you exactly where to meet on the way back."},{title:"Umrah peaks and Ramadan",body:"Jeddah–Makkah traffic and the Haram area get far busier in Ramadan and peak Umrah weeks. Allow extra time for airport departures and book vans and SUVs early."},{title:"Night arrivals",body:"Many international flights land at night or before dawn. Transfers run 24/7 — pre-book so the car is waiting rather than searched for at 3 am."},{title:"Luggage and zamzam",body:"Umrah families often carry more than expected, including zamzam on the way home. Tell us the number of large cases and the vehicle is sized to match."},{title:"Summer heat",body:"From late spring to autumn, plan outdoor Ziyarat stops for early morning or after sunset, with the car close by between stops."},{title:"Entry to Makkah",body:"Only Muslims may enter the city limits of Makkah. Non-Muslim visitors to Saudi Arabia can use our Jeddah, Madinah, Taif and AlUla services."}],u=[{point:"Door to door",car:"Yes — airport or hotel to hotel",train:"Station to station; a transfer is needed at each end"},{point:"Luggage",car:"All bags in one vehicle, loaded by the driver",train:"Carried through the stations"},{point:"Family or group",car:"One fare for the whole car",train:"A ticket per person"},{point:"Timetable",car:"Leave when you are ready, 24/7",train:"Fixed departures"},{point:"Stops on the way",car:"Prayer, meal or luggage stops on request",train:"None"}],v=[{q:"How do I get from Jeddah Airport to my Makkah hotel?",a:`The simplest way is a pre-booked private car from your JED terminal to your hotel — about ${f.km} km and ${f.time}, with your luggage in the same vehicle. We track your flight, so a delay moves the pickup.`},{q:"Can the car take us to the door of our Makkah hotel?",a:"The driver takes you as close as vehicles are permitted. Around Masjid al-Haram some roads are closed at peak and prayer times, and the driver uses the nearest allowed drop-off point."},{q:"Can we travel from Makkah to Madinah by car?",a:`Yes. It is about ${h.km} km and ${h.time} of driving. Tell the driver your preferred prayer and rest stops when you book.`},{q:"What if we have elderly parents or small children?",a:"Say so when you book. An SUV or van gives more room and easier boarding, and Ziyarat days can be planned with longer waiting stops."},{q:"Do I need to stop at a Miqat?",a:"That depends on where you are travelling from and on your own religious circumstances, which we cannot advise on. If your route passes a Miqat and you want a stop, tell us when you book and we will plan it."},{q:"How do I pay?",a:"Cash to the driver or bank transfer. An electronic receipt is available on request."}],w=[{title:"Send your trip",desc:"Form or WhatsApp: pickup, drop-off, date, passengers, luggage and flight number if it is an airport trip."},{title:"Agree one fare",desc:"We confirm the vehicle and one fixed fare before anything is booked — no meter, no surge."},{title:"Driver details",desc:"Name and number arrive on WhatsApp before pickup. We track your flight."},{title:"Ride & pay",desc:`${k} free waiting. Pay cash or by bank transfer.`}],x=[{category:"Booking",question:"How do I book a private taxi in Makkah?",answer:"Send your pickup, drop-off, date, passengers and luggage by the form or on WhatsApp. We reply with the vehicle and one fixed fare before anything is booked — no meter and no surge."},{category:"Airport",question:"Can I book a private transfer from Jeddah Airport to Makkah?",answer:`Yes. Jeddah Airport (JED) to Makkah is about ${f.km} km and ${f.time}. The driver meets you after baggage claim, we track your flight, and the first ${k} of waiting is free.`},{category:"Intercity",question:"Can I travel privately from Makkah to Madinah?",answer:`Yes. Makkah to Madinah is about ${h.km} km — ${h.time} of driving. A private car goes hotel to hotel with prayer and rest stops on request, and the return trip can be booked at the same time.`},{category:"Hotels",question:"Can I request hotel pickup in Makkah?",answer:"Yes. Give us the hotel name and the driver comes to the entrance. Near Masjid al-Haram the car may have to wait at the nearest permitted point during prayer times; the driver tells you where."},{category:"Ziyarat",question:"Can I book Makkah Ziyarat transportation?",answer:"Yes. A private car takes you between the sites you choose, such as Jabal al-Nour, Jabal Thawr, Mina, Muzdalifah and Arafat, and waits at each stop. We provide transport only, not religious guidance."},{category:"Hourly",question:"Can I hire a private driver by the hour in Makkah?",answer:"Yes. Book a car and driver for a block of hours or a full day; the car waits between stops. Send your date, start time and hours needed and we confirm the fare before booking."},{category:"Vehicles",question:"Which vehicle should I choose for my family?",answer:"A sedan fits individuals and couples with normal luggage. A GMC or full-size SUV, or a Hyundai Staria, suits families with more luggage. A Hiace van or coaster suits larger groups. We confirm the vehicle against your passenger and luggage count."},{category:"Vehicles",question:"Can you provide a GMC or a Hyundai Staria?",answer:"Both are in the vehicle categories available through our partner network. Availability is confirmed for your date, route and passenger count when we quote."},{category:"Groups",question:"Can you arrange a large bus for a group?",answer:"Coasters and larger coaches are arranged on request through our partner network. Send the group size, dates and routes and we confirm what is available."},{category:"Corporate",question:"Can I request corporate transportation in Makkah?",answer:`Yes. Email your company details and trip list for a written quote. ${d.D2}`},{category:"Booking",question:"Can I cancel or change a booking?",answer:"Yes. Cancellation is free up to 24 hours before pickup, and time or address changes can be made on WhatsApp."},{category:"Booking",question:"Do the drivers speak English?",answer:"Yes. Drivers in our partner network speak English and Arabic, and trips run 24 hours a day."}],y=[{href:"/guides/makkah-hotel-haram-dropoff-guide",label:"Makkah hotel drop-off near the Haram"},{href:"/guides/jeddah-airport-to-makkah-guide",label:"Jeddah Airport to Makkah: car, train and bus compared"},{href:"/guides/makkah-to-madinah-transport-guide",label:"Makkah to Madinah: taxi, train or bus"},{href:"/blog/makkah-taxi-fares-cost-guide",label:"How taxi fares in Makkah are worked out"},{href:"/blog/makkah-ziyarat-taxi-holy-sites-tour",label:"Makkah Ziyarat by taxi: the holy sites"},{href:"/services/umrah-transport",label:"Umrah transport service"}],z={"private-driver":{slug:"private-driver",kind:"service",name:"Private Driver",nameAr:"سيارة مع سائق",title:"Private Driver in Makkah | Chauffeur by the Hour or Full Day",metaDescription:"Hire a private driver in Makkah by the hour or for a full day — meetings, shopping, family errands and Ziyarat. Fare agreed before booking, 24/7.",h1:"Private Driver & Chauffeur Service in Makkah",eyebrow:"Car with driver \xb7 Makkah",heroImage:"/locations/makkah-og.webp",heroAlt:"Minarets and the colonnaded facade of the Haram complex in Makkah at sunset",intro:`A private driver in Makkah is a car and chauffeur booked for a block of hours or a whole day. The car waits outside every stop — a meeting, a shopping trip, a family visit, a Ziyarat — so you never re-book a ride or search for a taxi at the Haram after prayers. Waiting during prayers is covered by the hours you book; the ${k} free-waiting rule is for one-way transfers.`,facts:[{label:"Ziyarat stops",value:"Jabal al-Nour \xb7 Thawr \xb7 Mina \xb7 Arafat"},{label:"Near the Haram",value:"Drop-off at the nearest permitted point"},{label:"Jeddah day",value:`About ${g.km} km each way`},{label:"Booked as",value:"Hours or a full day"}],blocks:[{type:"cards",eyebrow:"Who books a driver in Makkah",heading:"Four kinds of Makkah day",items:[{title:"The family day",body:"Elderly parents, children and shopping bags in one vehicle, with the driver timing pickups around prayer times instead of the other way round."},{title:"The Ziyarat day",body:"Jabal al-Nour, Jabal Thawr, Mina, Muzdalifah and Arafat in one half-day, with waiting time at each stop. Transport only — no religious guidance."},{title:"The business day",body:"Hotel managers, suppliers or a property viewing in the city — the car waits between appointments and drops you back before the next prayer."},{title:"The Makkah–Jeddah day",body:`A morning in Makkah and an afternoon in Jeddah, or the reverse. Makkah to Jeddah is about ${g.km} km each way.`}]},{type:"compare",heading:"A private driver, or a taxi after each prayer?",intro:"Roads near the Haram close and fill quickly at prayer times, so in Makkah the hardest part of the day is often the ride back to the hotel.",options:[{title:"A taxi when you need one",tone:"ink",when:["Your hotel is within walking distance of the Haram","One trip out in the day, such as a single Ziyarat","Adults travelling light"]},{title:"One driver for the day",tone:"green",when:["Your hotel is in Aziziyah, Al Awali or another district away from the Haram","Elderly parents or young children in the group","Ziyarat, shopping and a family visit in one day"]}]},{type:"table",heading:"Hourly hire in Makkah: what you can book",columns:["Use","How it is booked"],rows:[["Half-day Ziyarat","A block of hours with waiting at each site"],["Full-day city driver","Start time, hours and a rough list of stops"],["Corporate meetings","Written quote by email; invoicing via our sister company"],["Makkah plus Jeddah or Taif","Full-day hire or a transfer with a timed return"]]},{type:"vehicles",heading:"Which car for a Makkah family day",intro:"In Makkah the deciding factor is usually the size of the family, not luxury. Models are supplied through our partner network; the car for your date is confirmed with the quote.",items:[{tier:"Sedan",models:["toyota-camry"],bestFor:"Up to four pilgrims with light bags, for Ziyarat or a move between hotels.",waPrefill:"Salam! Private driver in Makkah — sedan (Toyota Camry).\n• Date & start time: \n• Hours needed: \n• Hotel & district: \n• Stops planned: \n• Passengers: \n(ref: makkah-private-driver)"},{tier:"Family van",models:["hyundai-staria","mercedes-v-class"],bestFor:"Grandparents, parents and children together, with room for the day's shopping.",waPrefill:"Salam! Private driver in Makkah — family van (Hyundai Staria / Mercedes V-Class).\n• Date & start time: \n• Hours needed: \n• Hotel & district: \n• Stops planned: \n• Passengers (incl. elderly): \n(ref: makkah-private-driver)"},{tier:"Full-size SUV",models:["gmc-yukon-xl"],bestFor:"Seven passengers with suitcases when changing hotels or heading to Jeddah Airport.",waPrefill:"Salam! Private driver in Makkah — GMC Yukon XL.\n• Date & start time: \n• Hours needed: \n• Hotel & district: \n• Stops planned: \n• Passengers & bags: \n(ref: makkah-private-driver)"},{tier:"Group vehicle",models:["toyota-hiace","toyota-coaster"],bestFor:"An Umrah group doing Ziyarat together in one vehicle.",waPrefill:"Salam! Private driver in Makkah — group vehicle (Toyota Hiace / Coaster).\n• Date & start time: \n• Hours needed: \n• Hotel & district: \n• Stops planned: \n• Group size: \n(ref: makkah-private-driver)"}]}],ctaHeading:"Request a private driver in Makkah",ctaBody:"Send your hotel name and district, how many people (and whether anyone is elderly), the stops you need and how many hours. We reply with the car and one fare for the whole block.",ctaLabel:"Request a Private Driver",waPrefill:"Salam! Private driver in Makkah (hourly / full day).\n• Date & start time: \n• Hours needed: \n• Hotel & district: \n• Stops planned: \n• Passengers: \n• Vehicle (Sedan / Family van / SUV / Group): \n(ref: makkah-private-driver)",form:{pickup:"Makkah",vehicle:"Sedan",tripType:"By the Hour"},pathB:{heading:"Drivers for an Umrah group or visiting team?",body:`Group organisers and companies can get one written quote by email for several cars across several days. ${d.D2}`,emailSubject:"Private driver RFQ — Makkah",emailBody:(0,d.V9)("a private driver / hourly hire in Makkah")},faqs:[{question:"How much is a private driver in Makkah?",answer:"Each booking is quoted on its own, because the fare depends on the vehicle, the number of hours and the stops. Send the date, your hotel, the hours and the places you want to visit on WhatsApp and we reply with one fixed fare for the whole block, usually within 1–2 hours."},{question:"Can the driver wait while we pray?",answer:"Yes. The car waits at the nearest permitted point and you message when you are ready. Allow extra time at prayer times, when roads near the Haram close."},{question:"Can the car drive right up to the Haram?",answer:"Not always. Roads around Masjid al-Haram are restricted, and at prayer times they close to most traffic. The driver drops you at the nearest point the authorities allow and you walk the last part. If anyone in the group is elderly, tell us when you book so we plan the closest practical pickup."},{question:"Can we do Ziyarat with the private driver?",answer:"Yes. A half-day block covers the usual sites — Jabal al-Nour, Jabal Thawr, Mina, Muzdalifah and Arafat — with the car waiting at each stop. The driver provides transport only, not religious guidance. If you only want the set route, the Makkah Ziyarat page is the simpler booking."},{question:"Can we go to Jeddah and back in one day?",answer:`Yes. Makkah to Jeddah is about ${g.km} km each way. Book it as a full-day hire, or as a transfer there and a timed return — tell us the plan and we suggest the better option.`},{question:"Which cars are available with a driver in Makkah?",answer:"Sedans such as the Toyota Camry, the Hyundai Staria and Mercedes V-Class for families, the GMC Yukon XL for seven with luggage, and the Toyota Hiace or Coaster for Umrah groups — all through our partner network. The exact car is confirmed for your date when we quote."}],related:[{href:"/services/makkah-ziyarat",label:"Makkah Ziyarat transportation",desc:"A set route between the sites"},{href:"/routes/jeddah-airport-to-makkah",label:"Jeddah Airport to Makkah",desc:"When you only need the airport leg"},{href:"/services/corporate",label:"Corporate transportation",desc:"Accounts and invoicing"},{href:"/routes/makkah-to-madinah",label:"Makkah to Madinah",desc:"A single transfer to Madinah"}],schema:{serviceType:"Hourly & full-day chauffeur hire"}}},A={slug:"makkah",name:"Makkah",nav:[{slug:"private-driver",label:"Private driver"}]},B=a=>{let b=(0,d.wP)(a);return`about ${b.km} km, ${b.time.replace("~","roughly ")}`},C={"jeddah-airport-to-makkah":{title:"Jeddah Airport to Makkah Taxi & Private Transfer | Fixed Fare",description:`Private transfer from Jeddah Airport (JED) to your Makkah hotel — ${B("jeddah-airport-to-makkah")}. We track your flight; fare agreed before booking. SUVs and vans for families. 24/7.`},"makkah-to-jeddah-airport":{title:"Makkah to Jeddah Airport Taxi & Private Transfer | Fixed Fare",description:`Private car from your Makkah hotel to Jeddah Airport (JED) — ${B("makkah-to-jeddah-airport")}. Pickup timed back from your flight; fare agreed before booking. 24/7.`},"makkah-to-madinah":{title:"Makkah to Madinah Taxi & Private Transfer | Fixed Fare",description:`Private car from Makkah to Madinah, hotel to hotel — ${B("makkah-to-madinah")}. Prayer and rest stops on request, one fare for the whole car, agreed before booking.`},"madinah-to-makkah":{title:"Madinah to Makkah Taxi & Private Transfer | Fixed Fare",description:`Private car from Madinah to Makkah, hotel to hotel — ${B("madinah-to-makkah")}. Luggage and family-sized vehicles, stops on request, fare agreed before booking.`},"jeddah-to-makkah":{title:"Jeddah to Makkah (Mecca) Taxi & Private Car | Fixed Fare",description:`Private car from any Jeddah hotel or address to Makkah — ${B("jeddah-to-makkah")}. One fixed fare for the whole car, agreed before booking. 24/7.`},"makkah-to-jeddah":{title:"Makkah to Jeddah Private Taxi | Hotels, Corniche & City",description:`Private car from Makkah to any address in Jeddah — ${B("makkah-to-jeddah")}. For flights, book the Jeddah Airport leg. Fare agreed before booking, 24/7.`},"makkah-to-taif":{title:"Makkah to Taif Taxi & Private Car | Al Hada Road Transfer",description:`Private car from Makkah to Taif up the Al Hada escarpment — ${B("makkah-to-taif")}. Day trip with a timed return, or a one-way transfer. Fare agreed before booking.`},"taif-to-makkah":{title:"Taif to Makkah Taxi & Private Car | Hotels & Airport Pickup",description:`Private car from Taif hotels, resorts or Taif Regional Airport to Makkah — ${B("taif-to-makkah")}. Al Hada or Al Sail road; fare agreed before booking, 24/7.`}},D=["jeddah-airport-to-makkah","makkah-to-jeddah-airport","jeddah-to-makkah","makkah-to-jeddah","makkah-to-madinah","madinah-to-makkah","makkah-to-taif","taif-to-makkah","riyadh-to-makkah","makkah-to-riyadh","madinah-airport-to-makkah","makkah-to-madinah-airport","makkah-to-kaec","makkah-to-yanbu","jeddah-airport-to-swissotel-makkah","jeddah-airport-to-fairmont-makkah","jeddah-airport-to-pullman-zamzam-makkah","jeddah-airport-to-hilton-suites-makkah","jeddah-airport-to-conrad-makkah","jeddah-airport-to-movenpick-makkah","jeddah-airport-to-makkah-clock-tower","makkah-clock-tower-to-madinah-markaziyah","makkah-hotels-to-taif-resorts"]}};